mapper.sql:
FROM fit_checkin_record cr
INNER JOIN fit_course_schedule s ON s.schedule_id = cr.schedule_id AND s.del_flag = '0'
LEFT JOIN fit_course_reservation r ON r.reservation_id = cr.reservation_id AND r.del_flag = '0'
INNER JOIN fit_member m ON m.member_id = cr.member_id AND m.del_flag = '0'
LEFT JOIN fit_course c ON c.course_id = s.course_id AND c.del_flag = '0'
LEFT JOIN fit_store st ON st.store_id = s.store_id AND st.del_flag = '0'
LEFT JOIN fit_coach coach ON coach.coach_id = s.coach_id AND coach.del_flag = '0'
LEFT JOIN fit_member_card mc ON mc.card_id = cr.card_id AND mc.del_flag = '0'
LEFT JOIN sys_user su ON su.user_id = cr.operator_user_id AND su.del_flag = '0'
WHERE cr.del_flag = '0'
AND cr.checkin_no LIKE CONCAT('%', #{bo.checkinNo}, '%')
AND r.reservation_no LIKE CONCAT('%', #{bo.reservationNo}, '%')
AND s.store_id = #{bo.storeId}
AND cr.schedule_id = #{bo.scheduleId}
AND cr.member_id = #{bo.memberId}
AND cr.card_id = #{bo.cardId}
AND s.coach_id = #{bo.coachId}
AND cr.checkin_type = #{bo.checkinType}
AND cr.checkin_status = #{bo.checkinStatus}
AND cr.checkin_time >= #{bo.checkinTimeStart}
AND cr.checkin_time <= #{bo.checkinTimeEnd}
AND s.schedule_date >= #{bo.scheduleDateStart}
AND s.schedule_date <= #{bo.scheduleDateEnd}

    AND (m.real_name LIKE CONCAT('%', #{bo.keyword}, '%')
        OR m.nickname LIKE CONCAT('%', #{bo.keyword}, '%')
        OR m.mobile LIKE CONCAT('%', #{bo.keyword}, '%')
        OR c.course_name LIKE CONCAT('%', #{bo.keyword}, '%')
        OR mc.card_name LIKE CONCAT('%', #{bo.keyword}, '%'))
